<?php try{$latestPosts=\App\Core\Database::connection()->query("SELECT title,slug,excerpt,cover_path,published_at FROM blog_posts WHERE status='published' ORDER BY featured DESC,published_at DESC LIMIT 3")->fetchAll();}catch(\Throwable){$latestPosts=[];}?>
<?php if($latestPosts):?><section class="commercial-section"><div class="sales-section-title"><span class="eyebrow">Conteúdo para crescer</span><h2>Aprenda com o Blog ApPlanner.</h2><p>Estratégias práticas para melhorar sua agenda, gestão e experiência dos clientes.</p></div><div class="blog-grid"><?php foreach($latestPosts as $post):?><article class="blog-card"><?php if($post['cover_path']):?><img src="<?=htmlspecialchars($post['cover_path'])?>" alt=""><?php else:?><div class="blog-placeholder">ApPlanner</div><?php endif;?><div><small><?=date('d/m/Y',strtotime($post['published_at']))?></small><h2><a href="/blog/<?=htmlspecialchars($post['slug'])?>"><?=htmlspecialchars($post['title'])?></a></h2><p><?=htmlspecialchars($post['excerpt'])?></p><a href="/blog/<?=htmlspecialchars($post['slug'])?>">Ler artigo →</a></div></article><?php endforeach;?></div><a class="btn btn-light mt-4" href="/blog">Ver todos os conteúdos</a></section><?php endif;?>
